namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public interface INotificationService
{
    Task<List<Notification>> GetNotificationsAsync();
    Task<List<Notification>> GetNotificationsSinceAsync(DateTime since);
}

public class NotificationService : INotificationService
{
    private readonly List<Notification> _notifications = new();
    private int _nextId = 1;
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.Add(new Notification(_nextId++, "Welcome to the notification center!", DateTime.UtcNow.AddMinutes(-10)));
        _notifications.Add(new Notification(_nextId++, "Your profile was updated successfully.", DateTime.UtcNow.AddMinutes(-5)));
        _notifications.Add(new Notification(_nextId++, "New feature: dark mode is now available.", DateTime.UtcNow.AddMinutes(-2)));

        // Simulate new notifications arriving over time
        _ = GenerateNotificationsAsync();
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(DateTime since)
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.Where(n => n.Timestamp > since).ToList());
        }
    }

    private async Task GenerateNotificationsAsync()
    {
        var messages = new[]
        {
            "Someone liked your post.",
            "You have a new follower.",
            "Your report is ready to download.",
            "Scheduled maintenance tonight at 11 PM.",
            "A new comment was added to your thread.",
            "Your subscription renews in 3 days.",
            "Security alert: new login from a new device.",
        };

        var random = new Random();
        while (true)
        {
            await Task.Delay(TimeSpan.FromSeconds(random.Next(7, 15)));
            lock (_lock)
            {
                var msg = messages[random.Next(messages.Length)];
                _notifications.Add(new Notification(_nextId++, msg, DateTime.UtcNow));
            }
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject INotificationService NotificationService
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications</h1>

@if (NotificationList is null)
{
    <p><em>Loading notifications...</em></p>
}
else
{
    <p>
        <span class="badge bg-primary">@NotificationList.Count</span>
        notification@(NotificationList.Count != 1 ? "s" : "")
    </p>

    <ul class="list-group">
        @foreach (var notification in NotificationList.OrderByDescending(n => n.Timestamp))
        {
            <li class="list-group-item">
                <strong>@notification.Message</strong>
                <small class="text-muted ms-2">@notification.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<Notification>? NotificationList { get; set; }

    private DateTime _lastChecked = DateTime.MinValue;

    protected override async Task OnInitializedAsync()
    {
        // Only fetch if not already restored from prerender state
        NotificationList ??= await NotificationService.GetNotificationsAsync();
        _lastChecked = NotificationList.Count > 0
            ? NotificationList.Max(n => n.Timestamp)
            : DateTime.UtcNow;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Start polling only after the page is interactive (not during prerender)
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), cancellationToken);

            var newNotifications = await NotificationService.GetNotificationsSinceAsync(_lastChecked);
            if (newNotifications.Count > 0)
            {
                NotificationList!.AddRange(newNotifications);
                _lastChecked = newNotifications.Max(n => n.Timestamp);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

